import * as core from './field-strips-core.mjs';
import {fieldStripsCopy as copy} from './field-strips-content.mjs';
import {fieldGrid} from './field-strips-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=x=>{try{return JSON.stringify(x,null,2);}catch{return 'Original data cannot be displayed here.';}};
const p=t=>`<p>${esc(t)}</p>`,button=(t,a='',primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${a}>${esc(t)}</button>`;
const labels={equalParts:'Equal parts and the whole',nested:'Take a part of the first amount',equivalent:'One amount, two names'};
const supportLabels={clue:'Clue opened',narration:'Hear requested',together:'Working together reported'};
const notices={unsupported:copy['Unsupported root'],unreadable:copy['Unreadable source'],model:copy['Unsupported model'],section:copy['Unreadable section'],case:copy['Unreadable case'],history:copy['Unreadable history'],teaching:copy['Unreadable teaching context'],report:copy['Report refusal'],cap:copy['Count ceiling'],noComparison:copy['No comparison'],context:copy['Draft status'],off:copy['Save-off'],storage:copy['Storage failure']};
const changed=(a,b)=>a&&b&&(a.columnsTaken!==b.columnsTaken||a.rowsTaken!==b.rowsTaken);
const canCompare=(v,c)=>v.modelSupported&&c.plan&&c.recordReadable&&c.supportReadable&&v.teachingReadable;
const pending=c=>!c.latest||changed(c.plan,c.latest)||c.contextChanged;
let visits=new WeakMap();
export function resetFieldStripsView(state){if(state&&typeof state==='object')visits.delete(state);else visits=new WeakMap();}
function visit(state,explorerId=''){let u=visits.get(state);if(!u||u.explorerId!==explorerId){u={explorerId,id:core.readFieldStrips(state).source?.cases?.[0]?.id,helper:null,step:0};visits.set(state,u);}return u;}
const words=['zero','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen','twenty','twenty-one','twenty-two','twenty-three','twenty-four','twenty-five','twenty-six','twenty-seven','twenty-eight','twenty-nine','thirty','thirty-one','thirty-two','thirty-three','thirty-four','thirty-five','thirty-six'];
export function fieldSpoken(text){return String(text).replace(/[\w.]+(?:\s*\/\s*[\w.]+)+/g,(token,offset,all)=>{const punctuation=token.match(/\.+$/)?.[0]||'',fraction=punctuation?token.slice(0,-punctuation.length):token,match=/^(\d+)\s*\/\s*(\d+)$/.exec(fraction);if(match&&!/[\w.]$/.test(all.slice(0,offset))&&!/^[\w.]/.test(all.slice(offset+token.length)))return `${words[Number(match[1])]??match[1]} over ${words[Number(match[2])]??match[2]}${punctuation}`;return token.replace(/\//g,' slash ');});}
function lines(s,z){const m=core.fieldMeasure(s,z),f=`${m.cellCount}/${m.totalCells}`,reduced=`${m.reducedNumerator}/${m.reducedDenominator}`;return [`First amount: ${z.columnsTaken}/${s.columns} of the original field.`,`Take: ${z.rowsTaken}/${s.rows} of that first amount.`,m.totalCells===1?`Taken cells: ${m.cellCount} of the one cell in the original field.`:`Taken cells: ${m.cellCount} of ${m.totalCells} equal cells in the original field.`,`Taken amount: ${f} of the original field.`,m.cellCount===0?'This takes none of the original field.':m.cellCount===m.totalCells?'This takes the whole original field.':f!==reduced?`Also named ${reduced} of the original field. This is another name for the same amount.`:'',m.totalCells===1?'The one cell is the original whole.':`Each small cell is 1/${m.totalCells} of the original field.`,m.smaller?'The current taken amount is smaller than the first amount.':'The current taken amount equals the first amount.',z.columnsTaken===0?`The first amount is empty. The chosen second fraction is still ${z.rowsTaken}/${s.rows}; taking it selects no cells.`:''].filter(Boolean);}
function readouts(s,z){return `<div class="field-readouts">${lines(s,z).map(p).join('')}</div>`;}
function startingField(v,c,diagram=false){const s=c.case,z=s.initial;if(!v.modelSupported)return `<pre>${esc(json({initial:z}))}</pre>`;return `${diagram?fieldGrid(s,z,'Starting field'):''}${p(`Starting first amount: ${z.columnsTaken}/${s.columns}. Starting fraction taken: ${z.rowsTaken}/${s.rows}.`)}${z.columnsTaken===s.firstTaken&&z.rowsTaken===s.secondTaken?p('This starting field already fits the request. It is not a learner-made comparison.'):''}${s.guided.length?p('Guided example given with this invitation'):''}`;}
function contextNotes(v,c,x){const overlap=core.fieldHelperOverlap(v,c.case.id,x.teachingBefore);return `${Object.entries(supportLabels).map(([k,label])=>p(`${label}: ${x.supportBefore[k]?'Recorded before this comparison':'Not recorded before this comparison'}`)).join('')}${Object.entries(labels).map(([k,label])=>p(`${label}: ${x.teachingBefore[k]?'Recorded before this comparison':'Not recorded before this comparison'}`)).join('')}${overlap.own.length?p(copy['Own helper']):''}${overlap.unknown.length?p(copy['Unknown helper']):''}${p(`Earlier comparison feedback available: ${x.afterFeedback?'yes':'no'}.`)}`;}
function checked(v,c,x,title='Your checked field',main=false){if(!v.modelSupported)return `<section class="field-checked"><h3>${esc(title)}</h3>${p(notices.model)}<pre>${esc(json(x))}</pre></section>`;const m=core.fieldMeasure(c.case,x);return `<section class="field-checked"><h3${main?' id="field-checked-focus" tabindex="-1"':''}>${esc(title)}</h3>${p('These are recorded comparisons, not a new check.')}${p(`This comparison used ${x.columnsTaken}/${c.case.columns} of the original field, then ${x.rowsTaken}/${c.case.rows} of that first amount.`)}${fieldGrid(c.case,x,title)}${p(`Computed from this checked plan: ${m.cellCount}/${m.totalCells} of the original field.`)}${core.fieldFeedback(v.source,x).map(t=>p('Recorded result: '+t)).join('')}${contextNotes(v,c,x)}</section>`;}
function hear(v,c){const s=c.case,t=[s.prompt,...(s.guided.length?['Guided example.',...s.guided]:[]),...lines(s,c.plan)];if(!c.recordReadable)t.push(notices.history);else if(!c.latest)t.push(notices.noComparison);else{const x=c.latest,m=core.fieldMeasure(s,x);t.push('Your checked field.',`This comparison used ${x.columnsTaken}/${s.columns} of the original field, then ${x.rowsTaken}/${s.rows} of that first amount.`,`Computed from this checked plan: ${m.cellCount}/${m.totalCells} of the original field.`,...core.fieldFeedback(v.source,x).map(t=>'Recorded result: '+t),`Earlier comparison feedback available: ${x.afterFeedback?'yes':'no'}.`);}return fieldSpoken(t.join(' '));}
function helper(v,u,c){if(!u.helper||!v.modelSupported)return '';if(u.helper==='clue')return `<section class="field-helper"><h2 id="field-helper-focus" tabindex="-1">Clue</h2>${p(c.case.clue)}${p(copy['No help edit'])}${button('Back to our field','data-field-close')}</section>`;const h=v.helpers[u.helper],s=h?.steps[u.step];if(!s)return '';const sc=core.fieldCaseView(v,s.caseId);return `<section class="field-helper"><h2 id="field-helper-focus" tabindex="-1">${esc(h.title)}</h2>${p(sc.case.title)}${h.steps.some(t=>t.caseId===c.case.id)?p(copy['Own helper']):''}${p(`Step ${u.step+1} of ${h.steps.length}`)}${fieldGrid(sc.case,s.plan,'Example field')}${p(s.text)}<nav>${button('Previous step',`data-field-step="-1" ${u.step===0?'disabled':''}`)}${button('Next step',`data-field-step="1" ${u.step===h.steps.length-1?'disabled':''}`)}</nav>${p(copy['No help edit'])}${button('Back to our field','data-field-close')}</section>`;}
function board(v,c){if(!v.modelSupported)return p(notices.model);if(!c.plan)return p(notices.case);const s=c.case,z=c.plan,controls=(key,remove,add,max)=>`<div class="field-control-pair">${button(remove,`data-field-move="${key}" data-delta="-1" ${z[key]===0?'disabled':''}`)}${button(add,`data-field-move="${key}" data-delta="1" ${z[key]===max?'disabled':''}`)}</div>`;return `<section class="field-board"><div class="field-material">${fieldGrid(s,z)}<div class="field-key"><span>Vertical stripes: first amount</span><span>Diagonal hatch: taken amount</span></div></div><div class="field-operation"><section><h3>Choose the first amount</h3>${p(`First amount: ${z.columnsTaken}/${s.columns} of the original field.`)}${controls('columnsTaken','Remove first strip','Add first strip',s.columns)}</section><section><h3>Take part of that amount</h3>${p(`Take: ${z.rowsTaken}/${s.rows} of that first amount.`)}${controls('rowsTaken','Remove taken row','Add taken row',s.rows)}</section>${button('Compare',`data-field-compare ${!canCompare(v,c)?'disabled':''}`,true)}</div><div class="field-measure">${p('The equal cuts are already drawn; the selected counts are yours to change.')}${readouts(s,z)}</div></section>`;}
const guide=copy.guide;
function task(v,u){const c=core.fieldCaseView(v,u.id),s=c.case,index=v.source.cases.findIndex(s=>s.id===u.id);if(!v.modelSupported)return `<h2 id="field-focus" tabindex="-1">${esc(s.title)}</h2>${p(notices.model)}<pre class="field-raw">${esc(json({source:s,draft:c.draft,record:c.record,support:c.support}))}</pre><details><summary>Choose an invitation</summary><nav class="field-chooser">${v.source.cases.map(item=>button(item.title,`data-field-case="${esc(item.id)}"`)).join('')}</nav></details><nav class="field-navigation">${button('Previous invitation',`data-field-next="-1" ${index===0?'disabled':''}`)}${button('Next invitation',`data-field-next="1" ${index===v.source.cases.length-1?'disabled':''}`)}</nav>`;return `<h2 id="field-focus" tabindex="-1">${esc(s.title)}</h2><p class="field-request">${esc(s.prompt)}</p>${board(v,c)}${!c.supportReadable?p(notices.case):''}${s.guided.length?`<div class="field-guided"><strong>Guided example · answer shown</strong>${s.guided.map(p).join('')}</div>`:''}${canCompare(v,c)&&c.latest&&pending(c)?`<p data-field-change>${esc(notices.context)}</p>`:''}${c.suppliedStart&&v.modelSupported?`<details><summary>Starting field</summary>${startingField(v,c)}</details>`:''}<div class="field-support">${v.modelSupported&&c.plan&&c.supportReadable?hearButton(hear(v,c),'Hear'):''}${button('Clue',`data-field-helper="clue" ${!v.modelSupported||!c.supportReadable?'disabled':''}`)}${button(c.support?.together?'Working together reported':'Working together',`data-field-together ${!v.modelSupported||!c.supportReadable?'disabled':''}`)}</div>${helper(v,u,c)}${!c.recordReadable?p(notices.history):c.latest?`<details class="field-checked-fold"><summary>Your checked field</summary>${v.modelSupported&&c.plan&&changed(c.plan,c.latest)?p('Your field changed since this comparison.'):''}${checked(v,c,c.latest,'Your checked field',true)}</details>`:v.modelSupported&&c.plan?p(notices.noComparison):''}<nav class="field-navigation">${button('Previous invitation',`data-field-next="-1" ${index===0?'disabled':''}`)}${button('Next invitation',`data-field-next="1" ${index===v.source.cases.length-1?'disabled':''}`)}</nav><details><summary>Choose an invitation</summary><nav class="field-chooser">${v.source.cases.map(s=>button(s.title,`data-field-case="${esc(s.id)}" aria-current="${s.id===u.id?'true':'false'}"`)).join('')}</nav></details><details><summary>More ideas</summary><div class="field-support">${Object.entries(labels).map(([k,label])=>button(v.helpers[k]?.title||label,`data-field-helper="${k}" ${!v.modelSupported||!v.helpers[k]||typeof v.root.teaching?.[k]!=='boolean'?'disabled':''}`)).join('')}</div>${c.supportReadable?p('Choose Working together if a grown-up is helping with this invitation. This records your report.'):''}${p('Before trying the rows, what do you expect: less, the same, or more than the first amount? Tell each other if you like. Nothing spoken is recorded or marked.')}</details>${v.modelSupported?`<details><summary>A ready-made field and a reason to discuss</summary>${fieldGrid(s,{columnsTaken:s.firstTaken,rowsTaken:s.secondTaken},'Ready-made fitting field')}${p(s.explanation)}${p(s.reasonPrompt)}${p('Tell a grown-up, or point to the cells. Nothing spoken is recorded or marked.')}</details>`:''}`;}
export function fieldStripsEntry(){return `<aside class="field-entry"><h3>A part of a part</h3>${p('Shade a first amount. Then take part of that amount.')}<a href="#studio/field-strips">Open Field Strips</a></aside>`;}
export function fieldStripsPage(state,explorerId=''){const v=core.readFieldStrips(state),u=visit(state,explorerId);let content;if(v.status==='missing')content=`<h2 id="field-focus" tabindex="-1">A part of a part</h2>${p(copy['beforeStart'])}${p(copy['beforeOpen'])}${button('Open Field Strips','data-field-start',true)}`;else if(v.status!=='ready')content=p(notices[v.status]||notices.unreadable);else{if(!v.source.cases.some(c=>c.id===u.id)){u.id=v.source.cases[0].id;u.helper=null;}content=`${['drafts','observations','support'].some(k=>v[k].status!=='ready'||v[k].unreadable.length)?p(notices.section):''}${!v.teachingReadable?p(notices.teaching):''}${task(v,u)}`;}return `<section data-field-strips-view><header class="field-heading"><h1>Field Strips</h1><a href="#desk">Keeper's Desk</a><a href="#notes">Grown-up notes</a></header><p id="field-status" role="status" aria-live="polite" tabindex="-1"></p>${content}<details><summary>Grown-up guide</summary>${p(copy['invitation'])}${p(copy['cuts'])}${guide.map(p).join('')}${v.status==='ready'?v.source.cases.map(s=>`<section data-field-guide-case="${esc(s.id)}"><h3>${esc(s.title)}</h3>${p(s.prompt)}${startingField(v,core.fieldCaseView(v,s.id),true)}</section>`).join(''):''}${p(copy['Reset note'])}</details><footer class="field-footer">${button('Download our notes','data-field-download')}<a href="#numbers">Number explorations</a><a href="#pathways/math">Math pathways</a></footer></section>`;}
export function fieldStripsNotes(state){const v=core.readFieldStrips(state);if(v.status==='missing')return '';return `<details class="panel field-notes"><summary>Field Strips</summary>${p(copy['Notes preface'])}${v.status==='ready'?`${p(v.source.title)}${p(v.source.origin)}${p(v.source.notice)}${['drafts','observations','support'].some(k=>v[k].status!=='ready'||v[k].unreadable.length)?p(notices.section):''}${!v.modelSupported?p(notices.model):''}${v.source.cases.map(s=>{const c=core.fieldCaseView(v,s.id);return `<section data-field-notes-case="${esc(s.id)}"><h3>${esc(s.title)}</h3><h4>Source invitation</h4>${p(s.prompt)}<h4>Starting field</h4>${startingField(v,c,true)}${v.modelSupported&&c.plan?`<h4>Current editable field</h4>${fieldGrid(s,c.plan,'Current editable field')}${readouts(s,c.plan)}`:''}${!c.draftReadable||(v.modelSupported&&!c.supportReadable)?p(notices.case):''}${!c.recordReadable?p(notices.history):c.record?`${p(`${c.record.compareCount} ${c.record.compareCount===1?'comparison':'comparisons'}`)}${checked(v,c,c.record.first,'First comparison')}${c.record.latest?checked(v,c,c.record.latest,'Latest retry'):''}`:''}${v.modelSupported&&c.supportReadable?Object.entries(supportLabels).map(([k,label])=>p(`${label}: ${c.support[k]?'Recorded here':'Not recorded here'}`)).join(''):''}${!v.modelSupported?`<pre>${esc(json({source:s,draft:c.draft,record:c.record,support:c.support}))}</pre>`:''}</section>`;}).join('')}${v.modelSupported?(v.teachingReadable?Object.entries(labels).map(([k,label])=>p(`${label}: ${v.root.teaching[k]?'Recorded for this explorer':'Not recorded for this explorer'}`)).join(''):p(notices.teaching)):''}`:p(notices[v.status]||notices.unreadable)}<details><summary>Original saved Field Strips data</summary><pre>${esc(json(state.fieldStrips))}</pre></details></details>`;}
export function bindFieldStrips(state,{notebook=()=>state,explorerId=()=>'',isActive=()=>true,save,render,focus,canExport,download,stopSpeech,stopSound}={}){const host=document.querySelector('[data-field-strips-view]');if(!host)return;const u=visit(state,explorerId()),boundExplorer=explorerId(),boundCase=u.id,boundHelper=u.helper,boundStep=u.step,boundSource=json(core.readFieldStrips(state).source);let boundRoot=state.fieldStrips;const live=el=>document.querySelector('[data-field-strips-view]')===host&&el.isConnected&&host.isConnected&&!el.closest('[hidden]')&&el.getClientRects().length>0&&notebook()===state&&explorerId()===boundExplorer&&isActive()&&window.location.hash==='#studio/field-strips'&&visits.get(state)===u&&u.id===boundCase&&u.helper===boundHelper&&u.step===boundStep&&state.fieldStrips===boundRoot&&json(core.readFieldStrips(state).source)===boundSource;
 const status=(t,take=false)=>{const box=host.querySelector('#field-status');if(box){box.textContent=t;if(take)box.focus();}};
 const refusal=r=>r.code==='report-safety'?notices.report:r.code==='compare-count-cap'?notices.cap:notices.case;
 const persist=()=>{try{const r=save?.();return r?.enabled===false?notices.off:r?.ok===false?notices.storage:'';}catch{return notices.storage;}};
 const redraw=(target='#field-focus',message='',write=false)=>{const note=write?persist():'';stopSpeech?.();stopSound?.();render?.();const next=document.querySelector('[data-field-strips-view]');if(!next)return;const box=next.querySelector('#field-status');if(box)box.textContent=note||message;if(note||message)next.querySelector('[data-field-change]')?.remove();const destination=next.querySelector(target);for(let ancestor=destination?.parentElement;ancestor&&ancestor!==next;ancestor=ancestor.parentElement)if(ancestor.tagName==='DETAILS')ancestor.open=true;destination?.focus();};
 const bind=(selector,fn)=>host.querySelectorAll(selector).forEach(el=>el.addEventListener('click',event=>{if(!live(el)){event.preventDefault();event.stopImmediatePropagation();return;}fn(el,event);}));
 const mutate=(r,target,message='')=>{if(!r.ok)return status(refusal(r),true);if(r.changed)redraw(target,message,true);return r;};
 bind('[data-field-start]',()=>{const r=core.createFieldStrips(state,canExport);if(!r.ok)return status(refusal(r),true);u.id=core.readFieldStrips(state).source.cases[0].id;redraw('#field-focus','',r.changed);});
 bind('[data-field-download]',()=>download?.());
 bind('[data-field-case]',el=>{u.id=el.dataset.fieldCase;u.helper=null;u.step=0;redraw();});
 bind('[data-field-next]',el=>{const cases=core.readFieldStrips(state).source.cases,index=cases.findIndex(c=>c.id===u.id),next=cases[index+Number(el.dataset.fieldNext)];if(next){u.id=next.id;u.helper=null;u.step=0;redraw();}});
 bind('[data-field-move]',el=>{const key=el.dataset.fieldMove,delta=Number(el.dataset.delta),r=core.moveFieldSelection(state,u.id,key,delta,canExport);if(!r.ok)return status(refusal(r),true);if(r.changed){const v=core.readFieldStrips(state),c=core.fieldCaseView(v,u.id),max=key==='columnsTaken'?c.case.columns:c.case.rows,direction=c.plan[key]===0?1:c.plan[key]===max?-1:delta,message=canCompare(v,c)?pending(c)?'Field changed. Compare when you want to keep this version.':'Field changed.':'Field changed. Comparing is unavailable while part of the saved comparison context cannot be read.';redraw(`[data-field-move="${key}"][data-delta="${direction}"]`,message,true);}});
 bind('[data-field-compare]',()=>{const r=core.compareFieldStrips(state,u.id,canExport);if(!r.ok)return status(refusal(r),true);if(r.changed)redraw('#field-checked-focus','',true);else status('This field and help context already match the kept comparison.');});
 bind('[data-field-together]',()=>mutate(core.noteFieldSupport(state,u.id,'together',canExport),'[data-field-together]','Working together reported.'));
 bind('[data-field-helper]',el=>{const type=el.dataset.fieldHelper,r=type==='clue'?core.noteFieldSupport(state,u.id,'clue',canExport):core.noteFieldTeaching(state,type,canExport);if(!r.ok)return status(refusal(r),true);u.helper=type;u.step=0;redraw('#field-helper-focus','',r.changed);});
 bind('[data-field-step]',el=>{const h=core.readFieldStrips(state).helpers[u.helper];if(!h)return;u.step=Math.max(0,Math.min(h.steps.length-1,u.step+Number(el.dataset.fieldStep)));redraw('#field-helper-focus');});
 bind('[data-field-close]',()=>{const type=u.helper;u.helper=null;redraw(`[data-field-helper="${type}"]`);});
 host.querySelectorAll('[data-speak]').forEach(el=>el.addEventListener('click',event=>{if(!live(el)){event.preventDefault();event.stopImmediatePropagation();return;}const r=core.noteFieldSupport(state,u.id,'narration',canExport);if(!r.ok){event.preventDefault();event.stopImmediatePropagation();status(refusal(r),true);return;}if(r.changed){boundRoot=state.fieldStrips;const note=persist(),v=core.readFieldStrips(state),c=core.fieldCaseView(v,u.id);el.dataset.speak=hear(v,c);if(note)status(note);else if(c.contextChanged)status(notices.context);}},true));
}
